import{af as t,z as r,J as a,ab as o}from"./chunks/framework.C1QHhBQn.js";const g=JSON.parse('{"title":"Pro3 (PR3)","description":"","frontmatter":{"aside":true},"headers":[],"relativePath":"devices/pro/pro3.md","filePath":"devices/pro/pro3.md"}'),i={name:"devices/pro/pro3.md"};function n(s,e,d,c,h,l){return r(),a("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1794235425000"},[...e[0]||(e[0]=[o('<h1 id="pro3-pr3" tabindex="-1">Pro3 (PR3) <a class="header-anchor" href="#pro3-pr3" aria-label="Permalink to &quot;Pro3 (PR3)&quot;">​</a></h1><p>Pro3 is a different hardware generation from <a href="/docs/pr/40/devices/pro/">ProN (PR2)</a>. The two generations share the same external appearance, so use the product code and hardware revision to identify your device before following its instructions. ProN (PR2) is now a legacy model and is no longer in production.</p><div class="tip custom-block"><p class="custom-block-title">Choose the matching LED guide</p><p>Pro3 hardware revisions 02–04 have four orange indicators, without the two separate GPS and mobile-network indicators found on ProN/PR2. See <a href="/docs/pr/40/guides/pro3-leds">Pro3 LED patterns</a> for battery, charging and restart guidance.</p></div><h2 id="images" tabindex="-1">Images <a class="header-anchor" href="#images" aria-label="Permalink to &quot;Images&quot;">​</a></h2><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/product-front/LB-DEV-PR2.png" alt="Pro3 tracker enclosure" tabindex="0"><figcaption>Pro3 tracker enclosure</figcaption></figure><p>The enclosure image is shared with ProN/PR2. It does not identify the internal electronics or LED layout.</p><h2 id="hardware-generations" tabindex="-1">Hardware generations <a class="header-anchor" href="#hardware-generations" aria-label="Permalink to &quot;Hardware generations&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>ProN / PR2</th><th>Pro3 / PR3</th></tr></thead><tbody><tr><td>LED layout</td><td>Four battery indicators plus two diagnostic indicators</td><td>Four orange indicators on revisions 02–04</td></tr><tr><td>Cellular platform</td><td>SIMCom SIM7000 family</td><td>SIMCom A76xx family</td></tr><tr><td>Controller</td><td>STM32WB55</td><td>STM32WLE5</td></tr><tr><td>Companion processor</td><td>ESP8285</td><td>ESP32 family; ESP32-C6FH4 on revision 04</td></tr><tr><td>GNSS receiver</td><td>Integrated SIM7000G receiver in the PR2 specification</td><td>Separate Quectel LC79HALMD on revision 04</td></tr><tr><td>Charger</td><td>Texas Instruments BQ25890H in the PR2 specification</td><td>Richtek RT9471 on revision 04</td></tr></tbody></table><p>This is a hardware comparison, not a complete Pro3 specification. Cellular bands, wireless features, charging limits and certifications must be checked for the supplied Pro3 revision. The <a href="/docs/pr/40/devices/pro/">PR2 specification download</a> applies to PR2 only.</p><h2 id="led-indicators" tabindex="-1">LED indicators <a class="header-anchor" href="#led-indicators" aria-label="Permalink to &quot;LED indicators&quot;">​</a></h2><p>The four orange lights share the normal battery display and startup sequences. Pro3 does not have a separate GPS or mobile-network colour table. In particular, the older ProN/PR2 example of two red and four orange lights is not the Pro3 layout.</p><p>See the <a href="/docs/pr/40/guides/pro3-leds">illustrated Pro3 LED guide</a>. When checking whether the tracker is communicating, use the latest successful communication in the app or portal rather than the lights alone.</p><h2 id="charging" tabindex="-1">Charging <a class="header-anchor" href="#charging" aria-label="Permalink to &quot;Charging&quot;">​</a></h2><p>Use the charging accessory and power supply specified for your Pro3 revision. Do not apply the PR2 voltage/current ratings or charging-time instructions to Pro3.</p><p>The normal charging display uses the four orange indicators. See <a href="/docs/pr/40/guides/pro3-leds#charging">Pro3 charging patterns</a> for the blinking and steady states. A steady high-charge display is not an exact 100% reading.</p><h2 id="get-help" tabindex="-1">Get help <a class="header-anchor" href="#get-help" aria-label="Permalink to &quot;Get help&quot;">​</a></h2><p>For specifications or troubleshooting, <a href="https://lightbug.io/contact/" target="_blank" rel="noreferrer">contact support</a> with the product code, device ID and hardware revision if known. Include whether the device is charging and a short video if you are asking about a repeating light pattern.</p>',17)])])}const u=t(i,[["render",n]]);export{g as __pageData,u as default};
